from dataclasses import dataclass

TTL_SECONDS = 1800          # every block expires
APPROVAL_ABOVE = 50         # wide reach requires a human

@dataclass
class Alert:
    id: str
    source_ips: list[str]
    confidence: float

def run(alert: Alert, *, dry_run: bool = True) -> str:
    if audit.already_handled(alert.id):          # idempotency
        return "skip: already handled"
    if alert.confidence < 0.9:
        return "skip: low confidence, goes to human triage"

    if len(alert.source_ips) > APPROVAL_ABOVE and not approvals.granted(alert.id):
        approvals.request(alert.id, reason="wide block")
        return "pending: awaiting approval"

    for ip in alert.source_ips:
        blocker.block(ip, ttl=TTL_SECONDS, dry_run=dry_run)
    audit.record(alert.id, action="block", ips=alert.source_ips, dry_run=dry_run)
    return "ok"
